function createSectionSwiper(rootEl,{containerSelector:containerSelector,nextSelector:nextSelector,prevSelector:prevSelector,paginationSelector:paginationSelector,options:options={}}={}){if(!window.Swiper){console.warn("Swiper is not loaded");return null}const container=rootEl.querySelector(containerSelector);if(!container){console.warn("Swiper container not found:",containerSelector);return null}const nextEl=nextSelector?rootEl.querySelector(nextSelector):null;const prevEl=prevSelector?rootEl.querySelector(prevSelector):null;const paginationEl=paginationSelector?rootEl.querySelector(paginationSelector):null;const baseConfig={slidesPerView:4,spaceBetween:24,loop:false,breakpoints:{0:{slidesPerView:1.2,spaceBetween:10},450:{slidesPerView:1.3,spaceBetween:10},568:{slidesPerView:2,spaceBetween:15},700:{slidesPerView:2.2,spaceBetween:15},768:{slidesPerView:2.5,spaceBetween:20},870:{slidesPerView:3,spaceBetween:20},1e3:{slidesPerView:4,spaceBetween:24}}};if(nextEl&&prevEl){baseConfig.navigation={nextEl:nextEl,prevEl:prevEl}}if(paginationEl){baseConfig.pagination={el:paginationEl,clickable:true}}const{breakpoints:userBreakpoints,pagination:_userPagination,navigation:_userNavigation,mergeBreakpoints:mergeBreakpoints,...restOptions}=options||{};const shouldMergeBreakpoints=mergeBreakpoints!==false;const finalConfig={...baseConfig,...restOptions};if(userBreakpoints){finalConfig.breakpoints=shouldMergeBreakpoints?{...baseConfig.breakpoints,...userBreakpoints}:userBreakpoints}else if(!shouldMergeBreakpoints){delete finalConfig.breakpoints}return new Swiper(container,finalConfig)}function initProductUI(){document.querySelectorAll("[data-color-selector]").forEach(el=>new ColorSelector(el));document.querySelectorAll("[data-size-selector]").forEach(el=>new SizeSelector(el));document.querySelectorAll("[data-gallery]").forEach(el=>new ProductGallery(el));document.querySelectorAll("[data-faq]").forEach(el=>new ProductAccordion(el));document.querySelectorAll('[data-section="product-recommendations"]').forEach(el=>new ProductRecommendationsSection(el));document.querySelectorAll('form[action="/cart/add"]').forEach(form=>new ProductForm(form));new SizeGuide}function updateMiniCartCount(){fetch("/cart.js").then(res=>res.json()).then(cart=>{const counter=document.getElementById("MiniCartCount");if(!counter)return;counter.textContent=cart.item_count}).catch(()=>{})}class ProductPageLoader{constructor(){this.onProductChange=this.onProductChange.bind(this);document.addEventListener("product:change",this.onProductChange)}async onProductChange(event){const handle=event.detail?.handle;if(!handle)return;const url=`/products/${handle}`;try{const response=await fetch(url,{headers:{"X-Requested-With":"XMLHttpRequest"}});if(!response.ok){console.error("[ProductPageLoader] Failed to load product page");return}const html=await response.text();const parser=new DOMParser;const doc=parser.parseFromString(html,"text/html");const newMain=doc.querySelector("#MainContent");const currentMain=document.querySelector("#MainContent");if(!newMain||!currentMain){console.warn("[ProductPageLoader] MainContent not found");return}currentMain.replaceWith(newMain);initProductUI();history.pushState({},"",url);document.dispatchEvent(new CustomEvent("product:updated"))}catch(error){console.error("[ProductPageLoader] Error loading product",error)}}}class ColorSelector{constructor(root){this.root=root;this.onClick=this.onClick.bind(this);this.root.addEventListener("click",this.onClick)}onClick(event){const btn=event.target.closest("[data-product-handle]");if(!btn)return;event.preventDefault();const handle=btn.dataset.productHandle;if(!handle)return;document.dispatchEvent(new CustomEvent("product:change",{detail:{handle:handle}}))}}class SizeSelector{constructor(root){this.root=root;this.inputs=Array.from(root.querySelectorAll('input[name="size"]'));this.output=document.querySelector("[data-availability-text]");this.addToCartBtn=document.querySelector("[data-add-to-cart]");this.texts=window.theme.strings;if(!this.inputs.length||!this.output){console.warn("[SizeAvailability] missing elements");return}this.bind();this.init()}bind(){this.inputs.forEach(input=>{input.addEventListener("change",()=>{this.update(input);this.updateAddToCartState()})})}init(){const checked=this.inputs.find(i=>i.checked);if(checked){this.update(checked)}this.updateAddToCartState()}update(input){const available=input.dataset.available==="true";const qty=parseInt(input.dataset.qty,10);let text=this.texts.outOfStock;if(available){if(!isNaN(qty)&&qty>0){text=this.texts.inStockQty+qty}else{text=this.texts.inStock}}this.output.textContent=text}updateAddToCartState(){if(!this.addToCartBtn)return;const hasAvailableVariant=this.inputs.some(input=>input.dataset.available==="true");this.addToCartBtn.disabled=!hasAvailableVariant;if(!hasAvailableVariant){this.output.textContent=this.texts.soldOut}}}class SizeGuide{constructor(){this.modal=document.querySelector("[data-size-guide]");if(!this.modal)return;this.bindEvents()}bindEvents(){document.addEventListener("click",e=>{if(e.target.closest("[data-size-guide-trigger]")){this.open()}if(e.target.closest("[data-size-guide-close]")||e.target.closest("[data-size-guide-overlay]")){this.close()}})}open(){this.modal.classList.remove("tw:hidden");this.modal.setAttribute("aria-hidden","false")}close(){this.modal.classList.add("tw:hidden");this.modal.setAttribute("aria-hidden","true")}}class ProductForm{constructor(form){this.form=form;this.handleSubmit=this.handleSubmit.bind(this);this.sizeInputs=this.form.querySelectorAll('input[name="size"]');this.variantInput=this.form.querySelector('input[name="id"]');this.errorEl=this.form.querySelector("#add-to-cart-error");this.form.addEventListener("submit",this.handleSubmit)}async handleSubmit(event){event.preventDefault();const selectedSize=[...this.sizeInputs].find(i=>i.checked);if(!selectedSize){this.errorEl.classList.remove("tw:hidden");return}this.errorEl.classList.add("tw:hidden");const variantId=selectedSize.dataset.variantId;if(!variantId)return;this.variantInput.value=variantId;const formData=new FormData(this.form);try{const response=await fetch("/cart/add.js",{method:"POST",body:formData,headers:{"X-Requested-With":"XMLHttpRequest"}});if(!response.ok){throw new Error(`Ошибка: ${response.status}`)}updateMiniCartCount()}catch(error){console.error("Cart error:",error)}}}class ProductGallery{constructor(element){this.root=element;this.bigImage=this.root.querySelector("[data-big]");this.thumbs=Array.from(this.root.querySelectorAll(".thumb"));this.initEvents()}initEvents(){if(!this.thumbs.length)return;this.thumbs.forEach(thumb=>{thumb.addEventListener("click",()=>{const url=thumb.dataset.large;if(!url)return;this.updateBigImage(url);this.updateActive(thumb)})})}updateBigImage(url){if(!this.bigImage)return;if(this.bigImage.tagName==="IMG"){this.bigImage.src=url;this.bigImage.srcset=url}else{const img=this.bigImage.querySelector("img");if(img){img.src=url;img.srcset=url}}}updateActive(selectedThumb){this.thumbs.forEach(thumb=>{const overlay=thumb.querySelector("[data-active]");if(overlay)overlay.dataset.active="false"});const selectedOverlay=selectedThumb.querySelector("[data-active]");if(selectedOverlay)selectedOverlay.dataset.active="true"}}class ProductAccordion{constructor(root){this.root=root;this.items=Array.from(root.querySelectorAll("[data-item]"));this.init()}init(){this.items.forEach(item=>{const btn=item.querySelector("[data-button]");const content=item.querySelector("[data-content]");if(!btn||!content)return;btn.addEventListener("click",()=>{const isOpen=content.dataset.active==="true";this.items.forEach(i=>{const c=i.querySelector("[data-content]");if(c)c.dataset.active="false";const icon=i.querySelector("[data-icon]");if(icon)icon.dataset.active="false"});if(!isOpen){content.dataset.active="true";item.querySelector("[data-icon]").dataset.active="true"}})})}}class ProductRecommendationsSection{constructor(sectionEl){this.sectionEl=sectionEl;this.productId=sectionEl.dataset.productId;this.sectionId=sectionEl.dataset.sectionId;if(!this.productId||!this.sectionId)return;this.fetchRecommendations()}async fetchRecommendations(){const url=`/recommendations/products?section_id=${this.sectionId}&product_id=${this.productId}`;try{const response=await fetch(url);if(!response.ok)return;const html=await response.text();const parser=new DOMParser;const doc=parser.parseFromString(html,"text/html");const newSection=doc.querySelector('[data-section="product-recommendations"]');if(!newSection){this.sectionEl.style.display="none";return}this.sectionEl.innerHTML=newSection.innerHTML;this.swiper=createSectionSwiper(this.sectionEl,{containerSelector:".js-product-recommendations-swiper",nextSelector:".swiper-button-next",prevSelector:".swiper-button-prev"})}catch(error){console.error("Failed to load product recommendations",error)}}}class DataActiveToggle{constructor(selector){this.buttons=document.querySelectorAll(selector);if(!this.buttons.length)return;this.bind()}bind(){this.buttons.forEach(button=>{button.addEventListener("click",()=>{this.toggle(button)})})}toggle(button){const isActive=button.dataset.active==="true";button.dataset.active=String(!isActive);button.setAttribute("aria-expanded",String(!isActive))}}class FooterAccordion{constructor(selector="[data-toggle-active]"){this.buttons=document.querySelectorAll(selector);if(!this.buttons.length)return;this.bind()}bind(){this.buttons.forEach(button=>{button.addEventListener("click",()=>{this.toggle(button)})})}toggle(button){const parent=button.closest("[data-footer-item]");if(!parent)return;const isActive=parent.dataset.active==="true";parent.dataset.active=String(!isActive);button.setAttribute("aria-expanded",String(!isActive))}}class RemoveFromCart{constructor(context=document){this.context=context;this.init()}init(){this.context.addEventListener("click",event=>{const button=event.target.closest("[data-cart-remove]");if(!button)return;event.preventDefault();this.removeItem(button)})}async removeItem(button){const key=button.dataset.cartRemove;if(!key)return;button.disabled=true;try{await fetch("/cart/change.js",{method:"POST",headers:{"Content-Type":"application/json","X-Requested-With":"XMLHttpRequest"},body:JSON.stringify({id:key,quantity:0})});if(window.location.pathname.includes("/cart")){window.location.reload()}}catch(error){console.error("Remove from cart error:",error)}finally{button.disabled=false}}}document.addEventListener("DOMContentLoaded",()=>{new ProductPageLoader;new RemoveFromCart(document);new DataActiveToggle("[data-toggle-active]");new FooterAccordion("[data-toggle-active]");initProductUI()});